package cn.paletale.companion;
import com.google.gson.Gson;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
/** Local-only per Minecraft account. Disk work is serialized, never on the render thread. */
final class PrivateChatStore {
 private static final SelfWhispers selfWhispers=new SelfWhispers();private static final Gson JSON=new Gson();private static final ScheduledExecutorService IO=Executors.newSingleThreadScheduledExecutor(r->{var t=new Thread(r,"paletale-private-chat");t.setDaemon(true);return t;});
 private static final Map<String,List<PrivateChat.Entry>> pending=new HashMap<>();
 private static final class Preferences {Map<String,String> aliases=new HashMap<>();Map<String,Boolean> pins=new HashMap<>();Map<String,Integer> unread=new HashMap<>();Map<String,Boolean> muted=new HashMap<>();}
 private static Preferences preferences=new Preferences();private static final Map<String,Preferences> preferenceWrites=new HashMap<>();
 static synchronized boolean pinned(String peer){ensure();String key=peer.toLowerCase(Locale.ROOT);return preferences.pins.containsKey(key)||peer.matches("[A-Za-z0-9_]{1,16}")&&preferences.pins.containsKey("收藏:"+key);}
 /** Do-not-disturb conversations collect messages but never count unread or ring for mentions. */
 static synchronized boolean muted(String peer){ensure();String key=peer.toLowerCase(Locale.ROOT);return preferences.muted.containsKey(key)||key.startsWith("收藏:")&&preferences.muted.containsKey(key.substring(3));}
 static synchronized void toggleMute(String peer){ensure();if(!ready||peer.length()>120)return;String key=peer.toLowerCase(Locale.ROOT);if(preferences.muted.remove(key)==null&&preferences.muted.size()<1000){preferences.muted.put(key,true);preferences.unread.remove(key);preferences.unread.remove("收藏:"+key);}revision++;savePreferences();}
 static synchronized int totalUnread(){ensure();if(!ready)return -1;return preferences.unread.entrySet().stream().filter(e->!e.getKey().equals("官方")).mapToInt(e->Math.max(0,e.getValue())).sum();}
 static synchronized int unread(String peer){ensure();return preferences.unread.getOrDefault(peer.toLowerCase(Locale.ROOT),0);}
 static synchronized void togglePin(String peer){ensure();if(!ready||peer.length()>120)return;String key=peer.toLowerCase(Locale.ROOT);if(preferences.pins.containsKey(key)||peer.matches("[A-Za-z0-9_]{1,16}")&&preferences.pins.containsKey("收藏:"+key)){preferences.pins.remove(key);preferences.pins.remove("收藏:"+key);}else if(preferences.pins.size()<1000)preferences.pins.put(key,true);revision++;savePreferences();}
 static synchronized void read(String peer){ensure();if(preferences.unread.remove(peer.toLowerCase(Locale.ROOT))!=null){revision++;savePreferences();}}
 static synchronized void readAll(){ensure();if(!ready||preferences.unread.isEmpty())return;preferences.unread.clear();revision++;savePreferences();}
 private static Path prefFile(String a){return file(a).resolveSibling(a+".preferences.json");}
 private static void savePreferences(){if(!ready)return;String a=account;var snapshot=new Preferences();snapshot.aliases=Map.copyOf(preferences.aliases);snapshot.pins=Map.copyOf(preferences.pins);snapshot.unread=Map.copyOf(preferences.unread);snapshot.muted=Map.copyOf(preferences.muted);boolean queued=preferenceWrites.containsKey(a);preferenceWrites.put(a,snapshot);if(queued)return;IO.schedule(()->{Preferences latest;synchronized(PrivateChatStore.class){latest=preferenceWrites.remove(a);}try{var f=prefFile(a);Files.createDirectories(f.getParent());var temp=Files.createTempFile(f.getParent(),"chat-prefs-",".tmp");try{Files.writeString(temp,JSON.toJson(latest));try{Files.move(temp,f,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,f,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}catch(Exception e){saveError="聊天偏好保存失败，请检查本地文件权限。";}},500,TimeUnit.MILLISECONDS);}

 private static String account="";private static List<PrivateChat.Entry> rows=List.of();private static boolean ready;private static long revision;private static volatile String importInfo="",saveError="";
 static String importInfo(){return importInfo;}static String saveError(){return saveError;}
 static synchronized void ensure(){String a=LedgerStore.account();if(a.equals(account))return;account=a;selfWhispers.clear();rows=List.of();preferences=new Preferences();ready=false;revision++;if(!a.matches("[a-fA-F0-9]{32}"))return;String selfName=LedgerStore.accountName();var file=file(a);IO.execute(()->{List<PrivateChat.Entry> loaded=List.of();Preferences prefs=new Preferences();try{var pf=prefFile(a);if(Files.isRegularFile(pf)&&Files.size(pf)<=1024*1024){var value=JSON.fromJson(Files.readString(pf),Preferences.class);if(value!=null&&value.pins!=null&&value.unread!=null&&value.pins.size()<=1000&&value.unread.size()<=11000)prefs=value;}}catch(Exception ignored){}try{if(Files.isRegularFile(file)&&Files.size(file)<=24*1024*1024){var entries=JSON.fromJson(Files.readString(file),PrivateChat.Entry[].class);if(entries!=null)loaded=PrivateChat.merge(List.of(),Arrays.asList(entries),a);}}catch(Exception ignored){}synchronized(PrivateChatStore.class){if(account.equals(a)){rows=SelfWhispers.repair(PrivateChat.merge(loaded,rows,a),selfName);prefs.unread.forEach((k,v)->{if(v!=null&&v>0)preferences.unread.merge(k,Math.min(10000,v),(x,y)->Math.min(10000,x+y));});preferences.pins=prefs.pins;if(prefs.muted!=null&&prefs.muted.size()<=1000)preferences.muted=new HashMap<>(prefs.muted);preferences.aliases=new HashMap<>();if(prefs.aliases!=null&&prefs.aliases.size()<=1000)prefs.aliases.forEach((k,v)->{if(k!=null&&v!=null&&k.length()<=103&&v.length()<=103)preferences.aliases.put(k.toLowerCase(Locale.ROOT),v);});ready=true;save(account,rows);revision++;savePreferences();}}});}
 static synchronized List<PrivateChat.Entry> entries(){ensure();return rows;}
 static synchronized long revision(){ensure();return revision;}
 static synchronized boolean ready(){ensure();return ready;}
 static synchronized void add(PrivateChat.Entry e){ensure();if(!account.equals(e.account()))return;e=alias(e);var selfDecision=selfWhispers.accept(e,resolveAlias(LedgerStore.accountName()));if(selfDecision.drop())return;if(selfDecision.replace()!=null){var copy=new ArrayList<>(rows);copy.remove(selfDecision.replace());rows=List.copyOf(copy);}var next=PrivateChat.appendLive(rows,e,account);if(next.equals(rows))return;rows=next;if(preferences.unread.size()>=11000){var keys=new HashSet<String>();for(var row:rows)keys.add(row.peer().toLowerCase(Locale.ROOT));preferences.unread.keySet().retainAll(keys);}if(!e.outgoing()&&!muted(e.peer()))preferences.unread.merge(e.peer().toLowerCase(Locale.ROOT),1,(x,y)->Math.min(10000,x+y));if(!e.outgoing()&&!e.channelKind().startsWith("favorite-")&&!e.channelKind().equals("private")&&isFavorite(e.senderId())&&!muted(e.senderId()))preferences.unread.merge("收藏:"+e.senderId().toLowerCase(Locale.ROOT),1,(x,y)->Math.min(10000,x+y));revision++;save(account,rows);savePreferences();}
 static synchronized void deleteEntries(String expected,List<PrivateChat.Entry> deleted){ensure();if(!ready||!account.equals(expected))return;var copy=new ArrayList<>(rows);for(var entry:deleted)copy.remove(entry);rows=List.copyOf(copy);revision++;save(account,rows);}
 static synchronized void migrate(String expected,String oldPeer,String newName){ensure();boolean group=oldPeer.startsWith("领地:")||oldPeer.startsWith("国家:");if(!ready||!account.equals(expected)||(group?!PrivateChat.scopeValid(newName):!newName.matches("[A-Za-z0-9_]{1,16}")))return;String old=oldPeer.startsWith("收藏:")?oldPeer.substring(3):oldPeer,next=group?old.substring(0,3)+newName:newName;if(next.equalsIgnoreCase(old))return;if(preferences.aliases.size()>=1000&&!preferences.aliases.containsKey(old))return;preferences.aliases.replaceAll((k,v)->v.equalsIgnoreCase(old)?next:v);preferences.aliases.remove(next.toLowerCase(Locale.ROOT));preferences.aliases.put(old.toLowerCase(Locale.ROOT),next);var unchanged=new ArrayList<PrivateChat.Entry>();var moved=new ArrayList<PrivateChat.Entry>();for(var e:rows){var value=alias(e);if(e.equals(value))unchanged.add(e);else moved.add(value);}rows=PrivateChat.merge(unchanged,moved,account);movePreference(old,next);if(!group)movePreference("收藏:"+old,"收藏:"+next);revision++;save(account,rows);savePreferences();}
 private static void movePreference(String old,String next){old=old.toLowerCase(Locale.ROOT);next=next.toLowerCase(Locale.ROOT);if(preferences.pins.remove(old)!=null)preferences.pins.put(next,true);if(preferences.muted.remove(old)!=null)preferences.muted.put(next,true);Integer count=preferences.unread.remove(old);if(count!=null)preferences.unread.merge(next,count,(a,b)->Math.min(10000,a+b));}
 private static String resolveAlias(String value){if(value==null)return "";String key=value;var seen=new HashSet<String>();while(seen.add(key.toLowerCase(Locale.ROOT))&&seen.size()<=1000){String next=preferences.aliases.get(key.toLowerCase(Locale.ROOT));if(next==null)break;key=next;}return key;}

 private static PrivateChat.Entry alias(PrivateChat.Entry e){String sender=resolveAlias(e.senderId()),peer=resolveAlias(e.peer()),scope=e.scope();if(e.channelKind().startsWith("favorite-")){scope=resolveAlias(scope);sender=scope;peer="收藏:"+scope;}else if(e.channelKind().equals("land")||e.channelKind().equals("nation"))scope=peer.substring(3);return new PrivateChat.Entry(e.account(),peer,e.outgoing(),e.time(),e.text(),e.channelKind(),scope,sender,e.originKind());}
 private static List<PrivateChat.Entry> normalizeImports(List<PrivateChat.Entry> entries){var groups=new LinkedHashMap<String,Map<String,List<PrivateChat.Entry>>>();for(var e:entries)if(e!=null){var canonical=alias(e);String key=canonical.channelKind()+"\0"+canonical.originKind()+"\0"+canonical.peer().toLowerCase(Locale.ROOT)+"\0"+canonical.senderId().toLowerCase(Locale.ROOT)+"\0"+canonical.outgoing()+"\0"+canonical.time()/1000+"\0"+canonical.text();groups.computeIfAbsent(key,k->new LinkedHashMap<>()).computeIfAbsent(e.peer().toLowerCase(Locale.ROOT)+"\0"+e.senderId().toLowerCase(Locale.ROOT),k->new ArrayList<>()).add(canonical);}var out=new ArrayList<PrivateChat.Entry>();for(var alternatives:groups.values())out.addAll(alternatives.values().stream().max(Comparator.comparingInt(List::size)).orElse(List.of()));return PrivateChat.merge(List.of(),out,account);}
 private static boolean isFavorite(String sender){return PaleTaleClient.FAVORITE_PRESENCE.cachedNames().stream().anyMatch(n->n.equalsIgnoreCase(sender));}
 static CompletableFuture<Integer> importLogs(java.time.LocalDate from,java.time.LocalDate to){String a=LedgerStore.account(),name=LedgerStore.accountName();var dir=net.fabricmc.loader.api.FabricLoader.getInstance().getGameDir().resolve("logs");return CompletableFuture.supplyAsync(()->{try{var result=PrivateChatLogImport.read(dir,a,name,from,to,java.time.ZoneId.systemDefault());synchronized(PrivateChatStore.class){if(!account.equals(a)||!ready)throw new IllegalStateException("账号已变化或正在载入");int before=rows.size();rows=SelfWhispers.repair(PrivateChat.merge(rows,normalizeImports(result.entries()),a),name);revision++;importInfo="扫描 "+result.files()+" 个日志，跳过 "+result.skipped()+" 个。";save(a,rows);return Math.max(0,rows.size()-before);}}catch(Exception e){throw new CompletionException(e);}},IO);}
 static CompletableFuture<Integer> importEntries(String expected,List<PrivateChat.Entry> entries){return CompletableFuture.supplyAsync(()->{synchronized(PrivateChatStore.class){if(!ready||!account.equals(expected))throw new IllegalStateException("账号已变化");int before=rows.size();rows=SelfWhispers.repair(PrivateChat.merge(rows,normalizeImports(entries),expected),LedgerStore.accountName());revision++;save(expected,rows);return Math.max(0,rows.size()-before);}},IO);}
 private static Path file(String a){return net.fabricmc.loader.api.FabricLoader.getInstance().getGameDir().resolve("paletale/private-chat-v1").resolve(a+".json");}
 private static synchronized void save(String a,List<PrivateChat.Entry> snapshot){if(!ready)return;boolean queued=pending.containsKey(a);pending.put(a,snapshot);if(queued)return;IO.schedule(()->{List<PrivateChat.Entry> latest;synchronized(PrivateChatStore.class){latest=pending.remove(a);}try{var f=file(a);Files.createDirectories(f.getParent());if(Files.isRegularFile(f)&&Files.size(f)<=24*1024*1024){Files.copy(f,f.resolveSibling(a+".backup.json"),StandardCopyOption.REPLACE_EXISTING);}var temp=Files.createTempFile(f.getParent(),"chat-",".tmp");try{Files.writeString(temp,JSON.toJson(latest));try{Files.move(temp,f,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ex){Files.move(temp,f,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}saveError="";}catch(Exception ignored){saveError="聊天保存失败，请检查本地文件权限。";}},500,TimeUnit.MILLISECONDS);}

 static void register(){net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents.ALLOW_GAME.register((message,overlay)->overlay||!ChatChannelIcons.message(message.getString()));net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents.END_CLIENT_TICK.register(c->{ClientCommandQueue.tick();ChatChannelIcons.tick();ChatCompletionPackets.tick();});net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents.GAME.register((message,overlay)->{var c=net.minecraft.client.Minecraft.getInstance();if(overlay||c.getCurrentServer()==null||!ServerAccess.isSimmc(c.getCurrentServer().ip))return;ensure();var parsed=PrivateChat.parse(message.getString(),LedgerStore.accountName(),System.currentTimeMillis(),LedgerStore.account());if(parsed.isEmpty())parsed=PrivateChat.official(message.getString(),System.currentTimeMillis(),LedgerStore.account());if(parsed.isEmpty())parsed=PrivateChat.favoriteGlobal(message.getString(),PaleTaleClient.FAVORITE_PRESENCE.cachedNames(),System.currentTimeMillis(),LedgerStore.account());parsed.ifPresent(PrivateChatStore::add);});net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientLifecycleEvents.CLIENT_STOPPING.register(client->{IO.shutdown();try{IO.awaitTermination(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});}
}
